package com.hajara.academy.portal;
import java.time.*;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api/portal/admin/certificate-drafts")
public class CertificateDraftController {
 private final JdbcTemplate db; private final CurrentUser current; private final AuditLog audit; private final CertificatePdfController pdf;
 public CertificateDraftController(JdbcTemplate db,CurrentUser current,AuditLog audit,CertificatePdfController pdf){this.db=db;this.current=current;this.audit=audit;this.pdf=pdf;}
 private void admin(Authentication a){if(!"ADMIN".equals(current.require(a).role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 private void log(Authentication a,HttpServletRequest r,String action,String details){audit.record(current.require(a).id,action,r,details);}
 @GetMapping public List<Map<String,Object>> all(Authentication a){admin(a);return db.queryForList("SELECT d.*,u.student_number FROM academy_certificate_drafts d JOIN portal_enrollments e ON e.id=d.enrollment_id JOIN portal_users u ON u.id=e.user_id ORDER BY d.id DESC");}
 @PostMapping @Transactional public Map<String,Object> create(Authentication a,HttpServletRequest r,@RequestBody Map<String,Object> body){admin(a);Long id=number(body.get("enrollmentId"));var rows=db.queryForList("SELECT u.full_name,b.status FROM portal_enrollments e JOIN portal_users u ON u.id=e.user_id JOIN academy_batches b ON b.id=e.batch_id WHERE e.id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Enrollment not found");if(!"COMPLETED".equals(rows.get(0).get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Complete the batch first");if(db.queryForObject("SELECT COUNT(*) FROM academy_certificates WHERE enrollment_id=?",Integer.class,id)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Already issued");if(db.queryForObject("SELECT COUNT(*) FROM academy_certificate_drafts WHERE enrollment_id=?",Integer.class,id)==0){String code="HIA-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(Locale.ROOT);db.update("INSERT INTO academy_certificate_drafts(enrollment_id,certificate_code,student_name,completion_date) VALUES(?,?,?,CURRENT_DATE)",id,code,rows.get(0).get("full_name"));log(a,r,"CERTIFICATE_DRAFT_CREATED","Enrollment #"+id);}return oneByEnrollment(id);}
 @PostMapping("/batch/{batchId}") @Transactional public Map<String,Object> batch(Authentication a,HttpServletRequest r,@PathVariable Long batchId){admin(a);if(db.queryForObject("SELECT COUNT(*) FROM academy_batches WHERE id=? AND status='COMPLETED'",Integer.class,batchId)==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Complete batch first");int created=0;for(Long id:db.queryForList("SELECT id FROM portal_enrollments WHERE batch_id=? AND status='ACTIVE'",Long.class,batchId)){if(db.queryForObject("SELECT COUNT(*) FROM academy_certificates WHERE enrollment_id=?",Integer.class,id)==0&&db.queryForObject("SELECT COUNT(*) FROM academy_certificate_drafts WHERE enrollment_id=?",Integer.class,id)==0){create(a,r,Map.of("enrollmentId",id));created++;}}return Map.of("created",created);}
 @PutMapping("/{id}") @Transactional public Map<String,Object> edit(Authentication a,HttpServletRequest r,@PathVariable Long id,@RequestBody Map<String,String> body){admin(a);one(id);String name=body.get("studentName");String date=body.get("completionDate");if(name==null||name.isBlank()||name.length()>180||name.chars().anyMatch(c->Character.isISOControl(c)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid name");LocalDate day;try{day=LocalDate.parse(date);}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid date");}db.update("UPDATE academy_certificate_drafts SET student_name=?,completion_date=?,updated_at=CURRENT_TIMESTAMP(6) WHERE id=?",name.trim(),day,id);log(a,r,"CERTIFICATE_DRAFT_EDITED","Draft #"+id);return one(id);}
 @PostMapping("/{id}/issue") @Transactional public Map<String,Object> issue(Authentication a,HttpServletRequest r,@PathVariable Long id){admin(a);var d=one(id);Long enrollment=((Number)d.get("enrollment_id")).longValue();if(db.queryForObject("SELECT COUNT(*) FROM academy_certificates WHERE enrollment_id=?",Integer.class,enrollment)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Already issued");db.update("INSERT INTO academy_certificates(enrollment_id,certificate_code,issued_at,display_name,completion_date) VALUES(?,?,CURRENT_TIMESTAMP(6),?,?)",enrollment,d.get("certificate_code"),d.get("student_name"),d.get("completion_date"));db.update("DELETE FROM academy_certificate_drafts WHERE id=?",id);log(a,r,"CERTIFICATE_ISSUED","Enrollment #"+enrollment);return Map.of("certificateCode",d.get("certificate_code"),"enrollmentId",enrollment);}
 @GetMapping("/{id}/preview") public ResponseEntity<byte[]> preview(Authentication a,@PathVariable Long id)throws java.io.IOException{admin(a);return pdf.renderDraft(one(id));}
 private Map<String,Object> oneByEnrollment(Long id){return db.queryForMap("SELECT * FROM academy_certificate_drafts WHERE enrollment_id=?",id);}
 private Map<String,Object> one(Long id){var rows=db.queryForList("SELECT * FROM academy_certificate_drafts WHERE id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return rows.get(0);}
 private Long number(Object v){try{return Long.valueOf(String.valueOf(v));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid enrollment ID");}}
}
